mapper.select:
SELECT COUNT(*)
FROM warehouse
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}

SELECT COUNT(*)
FROM product
WHERE company_id = #{companyId}
AND product_id = #{productId}
AND use_yn = 'Y'

SELECT lot_managed_yn
FROM product
WHERE company_id = #{companyId}
AND product_id = #{productId}
AND use_yn = 'Y'

SELECT COUNT(*)
FROM lot
WHERE company_id = #{companyId}
AND product_id = #{productId}
AND lot_id = #{lotId}

SELECT quantity
FROM stock
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND product_id = #{productId}

SELECT ls.quantity
FROM lot_stock ls
JOIN lot l
ON l.lot_id = ls.lot_id
WHERE ls.company_id = #{companyId}
AND ls.warehouse_id = #{warehouseId}
AND l.product_id = #{productId}
AND ls.lot_id = #{lotId}

mapper.update:
UPDATE lot_stock
SET quantity = quantity + #{differenceQty}
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND lot_id = #{lotId}
AND quantity + #{differenceQty} >= 0
AND EXISTS (
SELECT 1
FROM lot l
WHERE l.lot_id = lot_stock.lot_id
AND l.company_id = #{companyId}
AND l.product_id = #{productId}
)

UPDATE stock
SET quantity = quantity + #{differenceQty}
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND product_id = #{productId}
AND quantity + #{differenceQty} >= 0

UPDATE stocktake
SET
    warehouse_id = #{warehouseId},
    memo = #{memo},
    updated_at = CAST(
        SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
        AS TIMESTAMP
    ),
    updated_by = #{updatedBy}
WHERE company_id = #{companyId}
AND stocktake_id = #{stocktakeId}
AND status = 'DRAFT'

mapper.delete:
DELETE FROM stocktake_item
WHERE stocktake_id = #{stocktakeId}
AND EXISTS (
    SELECT 1
    FROM stocktake st
    WHERE st.stocktake_id = stocktake_item.stocktake_id
    AND st.company_id = #{companyId}
    AND st.status = 'DRAFT'
)

DELETE FROM stocktake
WHERE company_id = #{companyId}
AND stocktake_id = #{stocktakeId}
AND status = 'DRAFT'
